export default async function list({ previous, projectId }, ctx) {
  const s = previous ?? { cursor: null, tasks: [] },
    input = { projectId, limit: 200 };
  if (s.cursor) input.cursor = s.cursor;
  const r = await ctx.actions.call("todoist.list_tasks", input);
  if (!Array.isArray(r?.tasks) || !Object.hasOwn(r, "nextCursor"))
    throw Error("Invalid Todoist response");
  return {
    state: { cursor: r.nextCursor ?? null, tasks: s.tasks.concat(r.tasks) },
    more: !!r.nextCursor,
  };
}

