export default function next({ tasks, previous }) {
  const index = previous?.index ?? 0,
    t = tasks[index];
  if (t && (!t.id || typeof t.content !== "string")) throw Error("Invalid task");
  return {
    state: { index: index + (t ? 1 : 0) },
    more: !!t,
    top: !!t && !t.parent_id,
    id: t?.id ?? "no-task",
    content: t?.content ?? "",
  };
}

