export default async function ({ id, acknowledge, resolution }, ctx) {
  const key = "todoist-priority:" + id,
    s = await ctx.state.get(key);
  if (s?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect prior update " + key);
    await ctx.state.set(key, null);
    return { key, work: resolution === "absent" };
  }
  return { key, work: true };
}

