export default function select({ result, mapping }) {
  const key = String(result?.category ?? "").trim();
  const p = Object.hasOwn(mapping, key) ? mapping[key] : null;
  if (p !== null && (!Number.isInteger(p) || p < 1 || p > 4))
    throw Error("Priority must be 1 to 4");
  return { matched: p !== null, priority: p ?? 1, category: key };
}

